<?php use App\Support\Ui; $hour = (int) $now->format('H'); ?>
<div class="home-head">
    <div><span class="eyebrow"><?= $e(strtoupper($now->format('l, d M · g:i A'))) ?> IST</span><h1>Good <?= $hour < 12 ? 'morning' : ($hour < 17 ? 'afternoon' : 'evening') ?></h1><p>Today’s interviews, live status and what needs your attention.</p></div>
    <a class="button primary home-head-cta" href="<?= $e($url('admin/interview/new')) ?>"><?= Ui::icon('plus') ?>New interview</a>
