<?php if (($locationPending ?? 0) > 0): ?><a class="attention-bar" href="<?= $e($url('admin/locations')) ?>"><span class="attention-icon"><?= Ui::icon('pin') ?></span><span class="attention-copy"><strong><?= (int) $locationPending ?> upcoming interview<?= (int) $locationPending === 1 ? ' needs' : 's need' ?> a location</strong><small>Choose KPHB or Ameerpet for each candidate.</small></span><span class="attention-action">Assign now <?= Ui::icon('arrow') ?></span></a><?php endif; ?>
<section class="metric-strip card" aria-label="Today at a glance"><?php foreach ([['Today', $metrics['today'], 'calendar'], ['Remaining', $metrics['remaining'], 'clock'], ['Tool', $metrics['tool'], 'monitor'], ['Normal', $metrics['normal'], 'briefcase'], ['Resources free', $metrics['available'], 'check']] as [$label, $value, $icon]): ?><div><span><?= Ui::icon($icon) ?><?= $e($label) ?></span><strong><?= $e($value) ?></strong></div><?php endforeach; ?></section>
<div class="ops-grid">
