<aside class="now-next">
    <article class="card focus-card<?= $current ? ' live' : '' ?>"><span class="eyebrow"><?= $current ? '<span class="live-dot"></span>' : '' ?>HAPPENING NOW</span><?php if ($current): ?><div class="focus-candidate"><?= Ui::candidateAvatar($current, 'focus-avatar') ?><div><h2><?= $e($current['candidate_name']) ?><?= Ui::partnerBadge($current) ?><?= Ui::locationBadge($current) ?></h2><?php if ($current['candidate_deleted']): ?><span class="deleted-label">Deleted candidate</span><?php endif; ?></div></div><p><?= $e($current['company_name']) ?> · <?= $e($current['display_time']) ?></p><strong><?= $e($current['resource_name']) ?></strong><a class="text-link" href="<?= $e($url('admin/interview?id=' . $current['id'])) ?>">View booking <?= Ui::icon('arrow') ?></a><?php else: ?><h2>No live interview</h2><p>No interview from today’s schedule is happening now.</p><?php endif; ?></article>
    <article class="card focus-card"><span class="eyebrow">UP NEXT TODAY</span><?php if ($next): ?><div class="focus-candidate"><?= Ui::candidateAvatar($next, 'focus-avatar') ?><div><h2><?= $e($next['candidate_name']) ?><?= Ui::partnerBadge($next) ?><?= Ui::locationBadge($next) ?></h2><?php if ($next['candidate_deleted']): ?><span class="deleted-label">Deleted candidate</span><?php endif; ?></div></div><p><?= $e($next['start_local']->format('g:i A')) ?> · <?= $e($next['company_name']) ?></p><strong><?= $e($next['resource_name']) ?></strong><?php else: ?><h2>Nothing else today</h2><p>The remaining schedule for today is clear.</p><?php endif; ?></article>
    <nav class="card quick-links" aria-label="Shortcuts"><a href="<?= $e($url('admin/interviews')) ?>"><?= Ui::icon('list') ?>All interviews</a><a href="<?= $e($url('admin/candidates')) ?>"><?= Ui::icon('user') ?>Candidates</a><a href="<?= $e($url('admin/consultancies')) ?>"><?= Ui::icon('briefcase') ?>Consultancies</a><a href="<?= $e($url('admin/reports')) ?>"><?= Ui::icon('chart') ?>Reports</a></nav>
</aside>
